// GREEN — the minimum implementation the test demands
class SearchViewModel(private val repo: SearchRepo) {
    private val _results = MutableStateFlow(emptyList<Item>())
    val results: StateFlow<List<Item>> = _results

    fun query(q: String) {
        _results.value = repo.search(q).filter { !it.isExpired() }
    }
}

// Extract the decision logic behind an injectable dependency
class CheckoutTotal(
    private val taxRate: () -> Double,   // the seam
) {
    fun apply(subtotalUsd: Double): Double =
        subtotalUsd * (1 + taxRate())
}

// Characterization test — records TODAY's behavior before a refactor
@Test
fun `total adds the configured rate`() {
    val total = CheckoutTotal(taxRate = { 0.1 })
    assertEquals(110.0, total.apply(100.0))
}

