abstract class VersionCheckTask : DefaultTask() {
    @get:Input
    abstract val expected: Property<String>

    @get:InputFile
    abstract val propsFile: RegularFileProperty

    @TaskAction
    fun check() {
        val actual = propsFile.get().asFile.readText().trim()
        check(actual == expected.get()) {
            "expected ${expected.get()}, found $actual"
        }
    }
}

// Lazy: nothing runs until the task is actually requested
val checkVersion = tasks.register<VersionCheckTask>("checkVersion") {
    expected.set("2026.08.11")
    propsFile.set(layout.projectDirectory.file("version.properties"))
}

// Task is skipped when unchanged, cached on reuse, runs the action only when needed

// EAGER — runs on every build, even when nothing changed
allprojects {
    val hash = File("$rootDir/version").readText()   // I/O at configuration time
    tasks.create("printVersion") { doLast { println(hash) } }
}

// LAZY — configuration registers a skeleton; only the action touches files
allprojects {
    tasks.register("printVersion") {
        val v = providers.fileContents(rootProject.layout.projectDirectory
            .file("version")).asText
        doLast { println("version: ${v.get()}") }
    }
}

